    identityRows += '<tr><td style="font-family:' + (t.jobTitle?.fontFamily || 'Arial, sans-serif') + '; font-size:' + (t.jobTitle?.fontSize || 12) + 'px; color:' + (c.jobTitle || '#666666') + '; line-height:1.3; padding-bottom:3px;">' + jobParts.join(' &bull; ') + '</td></tr>';
